<?php require_once 'bootstrap.php';$u=require_login();$st=db()->prepare('SELECT * FROM certificates WHERE owner_sic_id=? ORDER BY issued_at DESC');$st->execute([$u['sic_id']]);$certs=$st->fetchAll();$pageTitle='Attestati';require '_header.php';?><section class="section-head"><div><span class="eyebrow">Achievement & Certificate Engine</span><h1>I miei traguardi</h1><p>Rank, Academy, milestone e altri traguardi verificabili.</p></div></section><?php if(!$certs):?><section class="card"><p>Gli attestati compariranno automaticamente al raggiungimento dei traguardi.</p></section><?php endif;?><div class="course-list"><?php foreach($certs as $c):?><article class="course"><span class="course-cat"><?=h($c['certificate_type'])?></span><h3><?=h($c['title'])?></h3><p><?=h($c['issued_at'])?></p><small><?=h($c['sic_id'])?></small><?php if($c['verify_token']):?><a class="btn small" href="certificate-verify.php?token=<?=urlencode($c['verify_token'])?>" target="_blank">Verifica / stampa</a><?php endif;?></article><?php endforeach;?></div><?php require '_footer.php';?>